import numpy as np

def is_separated(R_pts, B_pts, lines):
    def get_sig(pt, lines):
        sig = []
        for a, b, c in lines:
            val = a * pt[0] + b * pt[1] + c
            if val > 1e-7:
                sig.append(1)
            elif val < -1e-7:
                sig.append(-1)
            else:
                return None
        return tuple(sig)

    R_sigs = set()
    for pt in R_pts:
        sig = get_sig(pt, lines)
        if sig is None: return False
        R_sigs.add(sig)

    B_sigs = set()
    for pt in B_pts:
        sig = get_sig(pt, lines)
        if sig is None: return False
        B_sigs.add(sig)

    return not R_sigs.intersection(B_sigs)

def test_n(n, k):
    R_pts = []
    B_pts = []
    for i in range(2 * n):
        angle = 2 * np.pi * i / (2 * n)
        pt = (np.cos(angle), np.sin(angle))
        if i % 2 == 0:
            R_pts.append(pt)
        else:
            B_pts.append(pt)

    # Try random lines to see if they work
    for _ in range(20000):
        lines = []
        for _ in range(k):
            a = np.random.uniform(-1, 1)
            b = np.random.uniform(-1, 1)
            c = np.random.uniform(-1, 1)
            lines.append((a, b, c))
        if is_separated(R_pts, B_pts, lines):
            return True
    return False

for n in range(1, 7):
    for k in range(1, n + 1):
        res = test_n(n, k)
        print(f"n={n}, k={k}, works={res}")

