def test_n_plus_1(n, k):
    R_pts = []
    B_pts = []
    # Total 2n+1 points
    # B1, R1, B2, R2, ..., Bn, Rn, B(n+1)
    for i in range(2 * n + 1):
        angle = 2 * np.pi * i / (2 * n + 1)
        pt = (np.cos(angle), np.sin(angle))
        if i % 2 == 0:
            B_pts.append(pt)
        else:
            R_pts.append(pt)

    for _ in range(20000):
        lines = []
        for _ in range(k):
            a = np.random.uniform(-1, 1)
            b = np.random.uniform(-1, 1)
            c = np.random.uniform(-1, 1)
            lines.append((a, b, c))
        if is_separated(R_pts, B_pts, lines):
            return True
    return False

for n in range(1, 6):
